"use client";

import Link from "next/link";
import React, { useEffect, useState, useRef } from "react";
import { usePathname } from "next/navigation";
import Logo from "./Logo";
import SearchBar from "@/components/Search/SearchBar";
import api from "@/lib/axios";
import { ShoppingCart, Search, X } from "lucide-react";

const navLinks = [
  { name: "Products", href: "/products" },
  { name: "Support", href: "/support" },
  { name: "About", href: "/about" },
];

const Header: React.FC = () => {
  const [authenticated, setAuthenticated] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const pathname = usePathname();
  const searchRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const res = await api.get("/auth/me");
        setAuthenticated(res.status === 200);
      } catch {
        setAuthenticated(false);
      }
    };
    checkAuth();
  }, []);

  // Handle outside click to collapse search
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        searchRef.current &&
        !searchRef.current.contains(event.target as Node)
      ) {
        // Only collapse if search is empty
        if (searchQuery.trim() === "") {
          setIsSearchOpen(false);
        }
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [searchQuery]);

  const toggleSearch = () => {
    if (!isSearchOpen) {
      setIsSearchOpen(true);
    } else {
      // Collapse when clicking icon again
      setIsSearchOpen(false);
      setSearchQuery("");
    }
  };

  const handleSearch = (query: string) => {
    setSearchQuery(query);
    // Navigate to products page with search query
    window.location.href = `/products?q=${encodeURIComponent(query)}`;
  };

  const glassBase =
    "backdrop-blur-md  rounded-full px-4 py-2 " +
    "text-base font-medium transition-all duration-200 " +
    "focus:outline-none focus-visible:ring ring-primary/30";

  const glassInactive =
    "bg-white/10 hover:bg-primary/20 hover:shadow-lg text-neutral hover:text-primary";

  const glassActive = "bg-primary/30 shadow-lg text-primary border-primary/30";

  return (
    <header className="sticky top-0 z-30 w-full bg-base-100/70 backdrop-blur-lg border-b border-base-300">
      <nav className="max-w-7xl mx-auto flex items-center justify-between px-8 py-4">
        {/* Logo and Navigation Links - Left Side */}
        <div className="flex items-center gap-8">
          <Logo />
          <ul className="flex gap-6 ml-50">
            {navLinks.map((link) => {
              const isActive = pathname === link.href;

              return (
                <li key={link.name}>
                  <Link
                    href={link.href}
                    className={`border border-white/20 ${glassBase} ${
                      isActive ? glassActive : glassInactive
                    }`}
                  >
                    {link.name}
                  </Link>
                </li>
              );
            })}
          </ul>
        </div>

        {/* Search Functionality - Right Side */}
        <div className="flex items-center ml-50">
          {!isSearchOpen ? (
            // Search Icon - Default State
            <button
              onClick={toggleSearch}
              className="p-2 rounded-lg hover:bg-gray-100 transition-all duration-200"
              aria-label="Toggle search"
            >
              <Search className="w-5 h-5 text-gray-600" />
            </button>
          ) : (
            // Expanded Search Bar
            <div className="relative w-full max-w-md" ref={searchRef}>
              <SearchBar
                placeholder="Search products..."
                onSearch={handleSearch}
                defaultValue={searchQuery}
              />
              {/* Close Button */}
              <button
                onClick={() => {
                  setIsSearchOpen(false);
                  setSearchQuery("");
                }}
                className="absolute right-3 top-1/2 p-1 rounded-full bg-white/80 backdrop-blur-sm border border-gray-200 hover:bg-gray-100 transition-all duration-200"
                aria-label="Close search"
              >
                <X className="w-4 h-4 text-gray-600" />
              </button>
            </div>
          )}
        </div>

        {/* Auth Actions */}
        <div className="flex items-center gap-3">
          {authenticated ? (
            <>
              <Link
                href="/cart"
                className={`border border-white/20 ${glassBase} ${
                  pathname === "/cart"
                    ? glassActive
                    : "bg-primary/20 hover:bg-primary/20 text-primary"
                } px-6 flex items-center`}
              >
                Cart <ShoppingCart />
              </Link>

              <button
                onClick={async () => {
                  await api.post("/auth/logout");
                  window.location.reload();
                }}
                className={`border border-white/20 ${glassBase} bg-red-500/10 text-red-500 hover:bg-red-500/20`}
              >
                Logout
              </button>
            </>
          ) : (
            <Link
              href="/signup"
              className={`${glassBase} ${
                pathname === "/signup"
                  ? glassActive
                  : "border border-accent bg-white/20 text-primary hover:bg-primary/40 hover:text-white"
              } px-6`}
            >
              Get Started
            </Link>
          )}
        </div>
      </nav>
    </header>
  );
};

export default Header;
